//! Export the pinned native WHIR profiles without re-deriving soundness tables.
use pcs::whir::{Config, MAX_LOG_INV_RATE, MAX_LOG_N, MIN_LOG_INV_RATE, MIN_LOG_N};
fn ints(a: &[usize]) -> String {
    format!(
        "[]int{{{}}}",
        a.iter()
            .map(|x| x.to_string())
            .collect::<Vec<_>>()
            .join(",")
    )
}
fn main() {
    let out = std::env::args().nth(1).expect("output Go file");
    let mut s = String::from(
        "// Code generated by tools/leanvm-mixed/src/bin/config.rs; DO NOT EDIT.\n// leanVM da5c964831c993b011464e4fd4a573b7172d5295, pcs/src/whir/config.rs.\n// CREDIT: succinctlabs/flock (MIT OR Apache-2.0), bcc-research/bolt-rs (MIT).\n// Copyright (c) 2026 Bain Capital Crypto, LP and Ron Rothblum\n// Modifications copyright 2026 Succinct Labs, Benedikt Bunz, William Wang\n// SPDX-License-Identifier: Apache-2.0 OR MIT\npackage pcs\n\nvar profiles = map[[2]int]config{\n",
    );
    for rate in MIN_LOG_INV_RATE..=MAX_LOG_INV_RATE {
        for n in MIN_LOG_N..=MAX_LOG_N {
            let c = Config::for_rate(n, rate).unwrap();
            s += &format!(
                "{{{n},{rate}}}:{{initialK:{},levelKs:{},rates:{},queries:{},grinding:{},oods:{}}},\n",
                c.initial_k(),
                ints(c.level_ks()),
                ints(c.log_inv_rates()),
                ints(c.queries()),
                ints(c.grinding_bits()),
                ints(c.ood_samples())
            );
        }
    }
    s += "}\n";
    std::fs::write(out, s).unwrap();
}
